package com.deardiary.privateapp;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;
/** Untrusted site content never receives a diary bridge or diary WebView storage. */
public final class InstagramActivity extends Activity{
 private WebView web;private boolean closing=false,started=false;private TextView status;
 static boolean allowed(Uri u){if(u==null||!"https".equals(u.getScheme())||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443))return false;String h=u.getHost();return "instagram.com".equals(h)||"www.instagram.com".equals(h)||"m.instagram.com".equals(h)||"i.instagram.com".equals(h)||"facebook.com".equals(h)||"www.facebook.com".equals(h)||"m.facebook.com".equals(h)||"accountscenter.instagram.com".equals(h);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);
  ComponentName caller=getCallingActivity();long issued=getIntent().getLongExtra("issued",0);if(caller==null||!getPackageName().equals(caller.getPackageName())||!MainActivity.class.getName().equals(caller.getClassName())||(saved==null&&(issued<=0||SystemClock.elapsedRealtime()-issued<0||SystemClock.elapsedRealtime()-issued>5000))){finish();return;}
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(22,22,25));setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);Button close=new Button(this);close.setText("Close");close.setContentDescription("Close Instagram");close.setOnClickListener(v->shut());bar.addView(close);status=new TextView(this);status.setText("Instagram · In-app\nLogin is handled by Instagram");status.setTextColor(Color.WHITE);status.setTextSize(13);bar.addView(status,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);
  TextView privacy=new TextView(this);privacy.setText("Dear Diary does not collect your login. Instagram controls its page. Screenshots and app-switcher previews are allowed here.");privacy.setTextColor(Color.LTGRAY);privacy.setTextSize(11);privacy.setPadding(14,8,14,8);root.addView(privacy);
  web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebView.setWebContentsDebuggingEnabled(false);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setGeolocationEnabled(false);s.setSupportMultipleWindows(false);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMediaPlaybackRequiresUserGesture(true);s.setSaveFormData(false);s.setSafeBrowsingEnabled(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setFilterTouchesWhenObscured(true);
  web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback c){c.invoke(origin,false,false);}@Override public boolean onShowFileChooser(WebView w,android.webkit.ValueCallback<Uri[]> cb,FileChooserParams p){cb.onReceiveValue(null);return true;}});
  web.setDownloadListener((url,agent,disposition,mime,size)->status.setText("Downloads are disabled in this screen."));
  web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(!"https".equals(r.getUrl().getScheme()))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));return null;}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(allowed(r.getUrl()))return false;if(r.isForMainFrame())status.setText("This link is outside the allowed Instagram login sites.");return true;}@Override public void onPageStarted(WebView w,String url,android.graphics.Bitmap icon){if(!allowed(Uri.parse(url))){w.stopLoading();status.setText("Blocked an unsupported address.");}}@Override public void onReceivedSslError(WebView w,SslErrorHandler h,android.net.http.SslError e){h.cancel();status.setText("Secure connection failed. Close and try later.");}@Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())status.setText("Instagram could not load. Close and try again.");}});
  started=true;boolean restored=saved!=null&&web.restoreState(saved)!=null&&allowed(Uri.parse(web.getUrl()));if(!restored)web.loadUrl("https://www.instagram.com/reels/");
 }
 private void shut(){if(closing)return;closing=true;if(web!=null){web.stopLoading();web.onPause();web.loadUrl("about:blank");((android.view.ViewGroup)web.getParent()).removeView(web);web.destroy();web=null;}finish();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else shut();}
 @Override protected void onPause(){super.onPause();if(web!=null)web.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override protected void onSaveInstanceState(Bundle state){if(web!=null)web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(web!=null){web.destroy();web=null;}super.onDestroy();}
}
